SELECT "t0"."line_id", CASE WHEN "t0"."_ttrp_a_n15_0" IS NULL THEN NULL ELSE COALESCE("t5"."_ttrp_n_n15_0", 0) END AS "days_open"
FROM (SELECT "t"."line_id", "t"."request_number", "t"."item", "t"."quantity", "t"."way", "t"."customer", "t"."obligation_id", "t"."due", "t"."obligation_state", "p_f7cce9af"."recipe", "p_f7cce9af"."run", "p_f7cce9af"."entity", "p_f7cce9af"."key", "p_f7cce9af"."kind", "p_f7cce9af"."due" AS "due0", "p_f7cce9af"."state", "p_f7cce9af"."fulfilled_by", "p_f7cce9af"."fulfilled_at", "p_f7cce9af"."created_at", "p_f7cce9af"."created_at" AS "_ttrp_a_n15_0"
        FROM (SELECT "p_ff40000e"."line_id", "p_ff40000e"."request_number", "p_ff40000e"."item", "p_ff40000e"."quantity", "p_ff40000e"."way", "p_ff40000e"."customer0" AS "customer", "p_7d39f2a5"."id" AS "obligation_id", "p_7d39f2a5"."due", "p_7d39f2a5"."state" AS "obligation_state"
                FROM "p_ff40000e"
                    INNER JOIN "p_7d39f2a5" ON "p_7d39f2a5"."entity" = 'return_request_line' AND "p_7d39f2a5"."key" = CAST("p_ff40000e"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a5"."kind" = 'inbound' AND "p_7d39f2a5"."state" IN ('open', 'overdue', 'reopened')) AS "t"
            INNER JOIN "p_f7cce9af" ON "t"."obligation_id" = "p_f7cce9af"."id") AS "t0"
    LEFT JOIN (SELECT "t3"."_ttrp_a_n15_0" AS "_ttrp_k_n15_0__ttrp_a_n15_0", COUNT("p_58e569ee"."_ttrp_d_n15_0") AS "_ttrp_n_n15_0"
        FROM (SELECT "p_f7cce9af0"."created_at" AS "_ttrp_a_n15_0"
                FROM (SELECT "p_ff40000e0"."line_id", "p_ff40000e0"."request_number", "p_ff40000e0"."item", "p_ff40000e0"."quantity", "p_ff40000e0"."way", "p_ff40000e0"."customer0" AS "customer", "p_7d39f2a50"."id" AS "obligation_id", "p_7d39f2a50"."due", "p_7d39f2a50"."state" AS "obligation_state"
                        FROM "p_ff40000e" AS "p_ff40000e0"
                            INNER JOIN "p_7d39f2a5" AS "p_7d39f2a50" ON "p_7d39f2a50"."entity" = 'return_request_line' AND "p_7d39f2a50"."key" = CAST("p_ff40000e0"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a50"."kind" = 'inbound' AND "p_7d39f2a50"."state" IN ('open', 'overdue', 'reopened')) AS "t1"
                    INNER JOIN "p_f7cce9af" AS "p_f7cce9af0" ON "t1"."obligation_id" = "p_f7cce9af0"."id"
                GROUP BY "p_f7cce9af0"."created_at") AS "t3"
            INNER JOIN "p_58e569ee" ON "t3"."_ttrp_a_n15_0" < "p_58e569ee"."_ttrp_d_n15_0" AND "p_58e569ee"."_ttrp_d_n15_0" <= :as_of
        GROUP BY "t3"."_ttrp_a_n15_0") AS "t5" ON "t0"."_ttrp_a_n15_0" = "t5"."_ttrp_k_n15_0__ttrp_a_n15_0"
